'use strict';
const express=require('express'),multer=require('multer'),fs=require('fs'),path=require('path');const{db}=require('../db'),{DATA_DIR}=require('../paths'),{broadcast}=require('../ws');const sharp=require('../../../vendor/upscale/node_modules/sharp');const{createUpscaleService}=require('../mopixUpscale.cjs');
const router=express.Router(),service=createUpscaleService({db,dataDir:DATA_DIR,sharp,notify:p=>broadcast('MOPIX_UPSCALE_UPDATED',p)});const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:32*1024*1024,files:1}});
router.use((req,res,next)=>{if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress))return res.status(403).json({error:'Chỉ dùng trên máy này'});const origin=req.get('origin');if(origin&&!['http://localhost:'+req.socket.localPort,'http://127.0.0.1:'+req.socket.localPort].includes(origin))return res.status(403).json({error:'Nguồn yêu cầu không hợp lệ'});next()});
function readFile(file){const real=fs.realpathSync(file);if(!['uploads','videos'].some(dir=>real.startsWith(fs.realpathSync(path.join(DATA_DIR,dir))+path.sep)))throw Error('Ảnh không thuộc thư viện trên máy.');return fs.readFileSync(real)}
router.get('/',(_req,res)=>res.json(db.prepare('SELECT payload FROM mopix_upscales ORDER BY rowid DESC LIMIT 100').all().map(r=>JSON.parse(r.payload))));
router.get('/:id',(req,res)=>{const p=service.get(req.params.id);if(!p)return res.status(404).json({error:'Không tìm thấy tác vụ 4K.'});res.json(p)});
router.post('/:id/resume',(req,res)=>{try{res.json(service.resume(req.params.id))}catch(e){res.status(422).json({error:e.message})}});
router.post('/start',(req,res,next)=>upload.single('file')(req,res,e=>e?res.status(400).json({error:'Chọn một ảnh PNG, JPG hoặc WebP tối đa 32 MB.'}):next()),async(req,res)=>{try{
 let source;if(req.file){const id=require('crypto').randomUUID(),meta=await sharp(req.file.buffer,{limitInputPixels:100000000}).metadata();if(!['png','jpeg','webp'].includes(meta.format))throw Error('Chỉ hỗ trợ PNG, JPG và WebP.');const ext={png:'.png',jpeg:'.jpg',webp:'.webp'}[meta.format];const filename='upscale_input_'+id+ext;fs.writeFileSync(path.join(DATA_DIR,'uploads',filename),req.file.buffer);source={buffer:req.file.buffer,mime:req.file.mimetype,name:req.file.originalname,beforeUrl:'/uploads/'+filename}}
 else if(req.body.jobId){const j=db.prepare("SELECT * FROM jobs WHERE id=? AND media_type='image' AND status='completed' AND archived_at IS NULL").get(String(req.body.jobId));if(!j||!/^\/videos\/[^/]+\.(png|jpe?g|webp)$/i.test(j.video_url||''))throw Error('Chọn ảnh đã tạo trong thư viện.');source={buffer:readFile(path.join(DATA_DIR,'videos',path.basename(j.video_url))),name:j.prompt?.slice(0,80)||'Ảnh đã tạo',sourceJobId:j.id,beforeUrl:j.video_url}}
 else {const r=db.prepare('SELECT * FROM ref_images WHERE tag=? AND archived_at IS NULL').get(String(req.body.tag||''));if(!r)throw Error('Chọn ảnh nguồn trong thư viện.');source={buffer:readFile(r.filepath),name:r.original_name||r.filename,tag:r.tag,beforeUrl:'/uploads/'+r.filename}}
 res.status(202).json(await service.start(source))
 }catch(e){res.status(422).json({error:e.message||'Không gửi được ảnh 4K.'})}});
module.exports=router;
